-- MySQL source table and 100 employee records

CREATE DATABASE IF NOT EXISTS employee_db;

USE employee_db;

CREATE TABLE IF NOT EXISTS EMPLOYEE_RAW
(
    EMPLOYEE_ID       INT PRIMARY KEY,
    FIRST_NAME        VARCHAR(50),
    LAST_NAME         VARCHAR(50),
    GENDER            VARCHAR(10),
    DEPARTMENT        VARCHAR(50),
    JOB_TITLE         VARCHAR(100),
    HIRE_DATE         DATE,
    SALARY            DECIMAL(12,2),
    MOBILE_NUMBER     VARCHAR(15),
    EMAIL             VARCHAR(100),
    MANAGER_ID        INT,
    CITY              VARCHAR(50),
    COUNTRY           VARCHAR(50),
    EMPLOYMENT_STATUS VARCHAR(20)
);


commit;

-- Verify inserted data
SELECT COUNT(*) AS TOTAL_RECORDS FROM EMPLOYEE_RAW;

use employee_db;

select * from employee_raw;

select * from employee_raw where city is null;